// Ymatch homepage — Hero (LIGHT, bold + italic H1, single editorial photo
// on the right) + search row + USP marquee.
//
// Mobile: hero is a single column (no photo, no dimension-line motif),
// USP marquee replaces the photo as the visual anchor at the top.

function Hero({ onSearch }) {
  const { Icons } = window;
  const isMobile = window.useIsMobile(900);
  const popular = ["Timmerman", "Elektromonteur", "Lasser", "ZZP-opdracht", "Werkvoorbereider", "Uitvoerder"];

  return (
    <section id="top" style={{ position: "relative", padding: isMobile ? "32px 20px 56px" : "32px 40px 64px" }}>
      {/* Decorative blueprint dimension line — desktop only */}
      {!isMobile &&
      <div aria-hidden="true" style={{ position: "absolute", top: "32px", right: "40px", display: "flex", alignItems: "center", gap: "6px", fontFamily: "var(--font-mono)", fontSize: "10px", letterSpacing: ".08em", color: "var(--blue)", opacity: .55 }}>
          <span style={{ width: "10px", height: "1px", background: "var(--blue)" }} />
          <span style={{ width: "180px", height: "1px", background: "var(--blue)", position: "relative" }}>
            <span style={{ position: "absolute", left: 0, top: "-3px", width: "1px", height: "7px", background: "var(--blue)" }} />
            <span style={{ position: "absolute", right: 0, top: "-3px", width: "1px", height: "7px", background: "var(--blue)" }} />
          </span>
          <span>14 JAAR YMATCH</span>
        </div>
      }

      <div style={{
        maxWidth: "1200px", margin: "0 auto",
        display: "grid",
        gridTemplateColumns: isMobile ? "1fr" : "1.15fr 1fr",
        gap: isMobile ? "32px" : "64px",
        alignItems: "center"
      }}>
        {/* Left — headline + search */}
        <div>
          <div style={{ fontFamily: "var(--font-mono)", fontSize: "11px", fontWeight: 700, letterSpacing: ".08em", textTransform: "uppercase", color: "var(--orange)", display: "inline-flex", alignItems: "center", marginBottom: "20px", flexWrap: "wrap" }}>
            Eerlijk salaris · Persoonlijk contact · Reactie binnen 1 werkdag
          </div>

          <h1 style={{
            fontFamily: "var(--font-display)", fontWeight: 800,
            fontSize: isMobile ? "clamp(48px, 11vw, 64px)" : "clamp(52px, 6.2vw, 80px)",
            letterSpacing: "-.05em", lineHeight: ".92",
            color: "var(--ink)", margin: "0 0 20px", textWrap: "balance"
          }}>
            Voor <em style={{ fontStyle: "italic", fontWeight: 300 }}>vakmensen</em><br />
            die werk willen<br />
            dat <span style={{ color: "var(--orange)" }}>klopt</span>.
          </h1>

          <p style={{ fontFamily: "var(--font-display)", fontSize: isMobile ? "17px" : "17px", lineHeight: 1.5, color: "var(--muted)", margin: "0 0 24px", maxWidth: "520px" }}>
            Geen formulieren. Geen "marktconform". Wij bellen je morgen, met een naam
            aan de lijn, een eerlijk salaris op tafel en één vraag: <b style={{ color: "var(--ink)" }}>past dit bij je?</b>
          </p>

          {/* Search bar */}
          <div style={{
            background: "var(--card)", borderRadius: "var(--r)",
            padding: isMobile ? "6px 6px 6px 16px" : "8px 8px 8px 22px",
            display: "flex", alignItems: "center", gap: isMobile ? "8px" : "12px",
            maxWidth: "640px", boxShadow: "var(--shadow-sm)", border: "1px solid var(--line)"
          }}>
            <Icons.search size={20} stroke="var(--subtle)" />
            <input placeholder={isMobile ? "Zoek vacatures…" : "Functie, sector of stad…"}
            onKeyDown={(e) => e.key === "Enter" && onSearch?.(e.target.value)}
            style={{ flex: 1, minWidth: 0, border: 0, background: "transparent", fontFamily: "var(--font-display)", fontSize: "16px", fontWeight: 500, color: "var(--ink)", outline: "none", padding: "12px 0" }} />
            {!isMobile &&
            <>
                <div style={{ width: "1px", height: "32px", background: "var(--line-strong)" }} />
                <div style={{ display: "flex", alignItems: "center", gap: "6px", padding: "0 8px" }}>
                  <Icons.pin size={16} stroke="var(--subtle)" />
                  <span style={{ fontSize: "14px", fontWeight: 500, color: "var(--muted)" }}>Rotterdam</span>
                </div>
              </>
            }
            <button onClick={() => onSearch?.("")} style={{
              fontFamily: "var(--font-display)", fontWeight: 700, fontSize: "15px",
              color: "#fff", background: "var(--ink)", border: 0,
              padding: isMobile ? "13px 16px" : "13px 22px", borderRadius: "10px", cursor: "pointer", flexShrink: 0,
              display: "inline-flex", alignItems: "center", gap: "8px"
            }}
            onMouseEnter={(e) => e.currentTarget.style.background = "var(--ink-2)"}
            onMouseLeave={(e) => e.currentTarget.style.background = "var(--ink)"}>
              Zoek {!isMobile && <Icons.arrow size={16} stroke="#fff" />}
            </button>
          </div>

          {/* Popular chips */}
          <div style={{ display: "flex", alignItems: "center", gap: "8px", marginTop: "20px", flexWrap: "wrap" }}>
            <span style={{ fontFamily: "var(--font-mono)", fontSize: "11px", fontWeight: 700, letterSpacing: ".06em", textTransform: "uppercase", color: "var(--subtle)", marginRight: "4px" }}>
              Vaak gezocht:
            </span>
            {popular.map((p) =>
            <button key={p}
            onClick={() => onSearch?.(p)}
            style={{
              fontFamily: "var(--font-display)", fontSize: "13px", fontWeight: 500,
              color: "var(--ink)", background: "transparent",
              border: "1px solid var(--line-strong)",
              borderRadius: "var(--r-pill)", padding: "6px 14px", cursor: "pointer",
              transition: "all .14s"
            }}
            onMouseEnter={(e) => {e.currentTarget.style.borderColor = "var(--orange)";e.currentTarget.style.color = "var(--orange)";}}
            onMouseLeave={(e) => {e.currentTarget.style.borderColor = "var(--line-strong)";e.currentTarget.style.color = "var(--ink)";}}>
              {p}</button>
            )}
          </div>
        </div>

        {/* Right — single editorial photo (desktop only) */}
        {!isMobile && <HeroImage />}
      </div>
    </section>);

}

function HeroImage() {
  // One editorial image: real Ymatch office meeting, behind the Y-MATCH wall.
  // Card with brand top-border, concentric circles motif, and a stat lockup
  // overlay so the photo isn't just decoration but earns its place in the
  // brand narrative.
  return (
    <div style={{ position: "relative" }}>
      {/* Bolt cross-section motif behind the image */}
      <div aria-hidden="true" style={{ position: "absolute", top: "-30px", right: "-40px", width: "240px", height: "240px", borderRadius: "50%", border: "1.5px solid var(--orange)", opacity: .18, pointerEvents: "none" }} />
      <div aria-hidden="true" style={{ position: "absolute", top: "10px", right: "0", width: "140px", height: "140px", borderRadius: "50%", background: "var(--orange)", opacity: .08, pointerEvents: "none" }} />
      <div aria-hidden="true" style={{ position: "absolute", bottom: "-24px", left: "-32px", width: "180px", height: "180px", borderRadius: "50%", border: "1.5px solid var(--ink)", opacity: .10, pointerEvents: "none" }} />

      <div style={{
        position: "relative",
        background: "var(--card)", borderRadius: "var(--r-lg)",
        boxShadow: "var(--shadow-lg)", border: "1px solid var(--line)",
        overflow: "hidden"
      }}>
        <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: "4px", background: "var(--orange)", zIndex: 2 }} />
        <img
          src="data:image/jpeg;base64,"
          alt="Ymatch team in gesprek met vakmensen op kantoor in Capelle aan den IJssel"
          style={{ display: "block", width: "100%", height: "480px", objectFit: "cover", objectPosition: "center 40%" }} />
        
      </div>

      {/* Floating "online nu" chip, bottom-left */}
      <div style={{
        position: "absolute", bottom: "-18px", left: "-12px", zIndex: 3,
        background: "var(--card)", borderRadius: "var(--r-pill)",
        padding: "10px 16px 10px 12px", display: "inline-flex", alignItems: "center", gap: "10px",
        boxShadow: "var(--shadow-lg)", border: "1px solid var(--line)"
      }}>
        <span style={{ position: "relative", width: "10px", height: "10px" }}>
          <span style={{ position: "absolute", inset: 0, borderRadius: "50%", background: "var(--green)" }} />
          <span style={{ position: "absolute", inset: "-4px", borderRadius: "50%", background: "var(--green)", opacity: .25 }} />
        </span>
        <span style={{ fontFamily: "var(--font-mono)", fontSize: "11px", fontWeight: 700, letterSpacing: ".05em", textTransform: "uppercase", color: "var(--ink)" }}>90+ ACTUELE VACATURES NU LIVE

        </span>
      </div>

      {/* Floating stat chip, top-right */}
      <div style={{
        position: "absolute", top: "32px", right: "-20px", zIndex: 3,
        background: "var(--ink)", color: "#fff", borderRadius: "var(--r)",
        padding: "14px 18px", boxShadow: "var(--shadow-lg)",
        textAlign: "right", transform: "rotate(2deg)"
      }}>
        <div style={{ fontFamily: "var(--font-display)", fontWeight: 800, fontSize: "28px", lineHeight: 1, letterSpacing: "-.03em" }}>
          2.000<span style={{ color: "var(--orange)" }}>+</span>
        </div>
        <div style={{ fontFamily: "var(--font-mono)", fontSize: "9px", fontWeight: 700, letterSpacing: ".06em", textTransform: "uppercase", color: "rgba(255,255,255,.6)", marginTop: "4px" }}>
          bemiddelingen
        </div>
      </div>
    </div>);

}

function Marquee() {
  // USP marquee — replaces the original cities/sectors strip. These are
  // brand promises, not geography.
  const items = [
  "Wij bellen morgen",
  "Salaris altijd zichtbaar",
  "98 actieve vacatures",
  "Geen formulieren",
  "92% blijft langer dan een jaar",
  "Eerlijk over de uren",
  "Reactie binnen 24 uur",
  "Persoonlijke consultant",
  "1.000+ bemiddelingen sinds 2012"];

  const row = (key) =>
  <div key={key} style={{ display: "inline-flex", alignItems: "center", gap: "28px", padding: "0 14px", fontSize: "16px" }}>
      {items.map((t, i) =>
    <React.Fragment key={i}>
          <span style={{ fontFamily: "var(--font-display)", fontWeight: 800, fontSize: "clamp(22px, 3vw, 32px)", letterSpacing: "-.025em", color: "var(--ink)", whiteSpace: "nowrap" }}>{t}</span>
          <span style={{ width: "6px", height: "6px", borderRadius: "50%", background: "var(--orange)", flexShrink: 0 }} />
        </React.Fragment>
    )}
    </div>;

  return (
    <section aria-hidden="true" style={{
      borderTop: "1px solid var(--line)", borderBottom: "1px solid var(--line)",
      background: "var(--card)", overflow: "hidden", padding: "20px 0", height: "90px"
    }}>
      <div style={{ display: "flex", whiteSpace: "nowrap", animation: "ym-marquee 42s linear infinite" }}>
        {row("a")}{row("b")}{row("c")}
      </div>
    </section>);

}

Object.assign(window, { Hero, HeroImage, Marquee });